public protocol ScanProgressCallback : AnyObject {
    
    func onProgress(currentPath: String, scannedCount: UInt64, bytesScanned: UInt64) 
    
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
private let IDX_CALLBACK_FREE: Int32 = 0
// Callback return codes
private let UNIFFI_CALLBACK_SUCCESS: Int32 = 0
private let UNIFFI_CALLBACK_ERROR: Int32 = 1
private let UNIFFI_CALLBACK_UNEXPECTED_ERROR: Int32 = 2

// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceScanProgressCallback {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    static var vtable: UniffiVTableCallbackInterfaceScanProgressCallback = UniffiVTableCallbackInterfaceScanProgressCallback(
        onProgress: { (
            uniffiHandle: UInt64,
            currentPath: RustBuffer,
            scannedCount: UInt64,
            bytesScanned: UInt64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceScanProgressCallback.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onProgress(
                     currentPath: try FfiConverterString.lift(currentPath),
                     scannedCount: try FfiConverterUInt64.lift(scannedCount),
                     bytesScanned: try FfiConverterUInt64.lift(bytesScanned)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterCallbackInterfaceScanProgressCallback.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface ScanProgressCallback: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitScanProgressCallback() {
    uniffi_velora_ffi_fn_init_callback_vtable_scanprogresscallback(&UniffiCallbackInterfaceScanProgressCallback.vtable)
}

